    @staticmethod
    def merge(list_1, list_2):
        """
        Merge two lists while trying to keep the relative order of the elements.
        Warn if the lists have the same two elements in a different relative
        order.

        For static assets it can be important to have them included in the DOM
        in a certain order. In JavaScript you may not be able to reference a
        global or in CSS you might want to override a style.
        """
        # Build a set of all items for quick lookup
        all_items = set(list_1) | set(list_2)

        # Build adjacency graph of ordering constraints from both lists
        # graph[item] = set of items that must come after item
        graph = {item: set() for item in all_items}

        def add_constraints(lst):
            for i, item in enumerate(lst):
                for later_item in lst[i+1:]:
                    graph[item].add(later_item)

        add_constraints(list_1)
        add_constraints(list_2)

        # Check for cycles (conflicting constraints)
        def has_cycle():
            visited = set()
            rec_stack = set()

            def dfs(node):
                visited.add(node)
                rec_stack.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        if dfs(neighbor):
                            return True
                    elif neighbor in rec_stack:
                        return True
                rec_stack.remove(node)
                return False

            for node in all_items:
                if node not in visited:
                    if dfs(node):
                        return True
            return False

        if has_cycle():
            # Find a conflicting pair for the warning
            # We'll use a simple approach: find first pair that violates order
            for i, item1 in enumerate(list_1):
                for item2 in list_1[i+1:]:
                    # Check if list_2 has them in opposite order
                    try:
                        idx1 = list_2.index(item1)
                        idx2 = list_2.index(item2)
                        if idx1 > idx2:
                            warnings.warn(
                                'Detected duplicate Media files in an opposite order:\n'
                                '%s\n%s' % (item1, item2),
                                MediaOrderConflictWarning,
                            )
                            return list_1 + [x for x in list_2 if x not in list_1]
                    except ValueError:
                        pass

        # Topological sort to get final order
        in_degree = {item: 0 for item in all_items}
        for item in all_items:
            for neighbor in graph[item]:
                in_degree[neighbor] += 1

        # Use list_1 order as tiebreaker for items with no constraints
        order_index = {item: i for i, item in enumerate(list_1)}
        for item in list_2:
            if item not in order_index:
                order_index[item] = len(list_1) + list_2.index(item)

        queue = [item for item in all_items if in_degree[item] == 0]
        # Sort queue by original order in list_1, then list_2
        queue.sort(key=lambda x: order_index[x])

        result = []
        while queue:
            item = queue.pop(0)
            result.append(item)
            for neighbor in graph[item]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
            queue.sort(key=lambda x: order_index[x])

        return result
