class DjangoHelpFormatter(HelpFormatter):
    """
    Customized formatter so that command-specific arguments appear in the
    --help output before arguments common to all commands.
    """

    show_last = {
        "--version",
        "--verbosity",
        "--traceback",
        "--settings",
        "--pythonpath",
        "--no-color",
        "--force-color",
        "--skip-checks",
    }

    def _reordered_actions(self, actions):
        return sorted(
            actions, key=lambda a: set(a.option_strings) & self.show_last != set()
        )

    def add_usage(self, usage, actions, *args, **kwargs):
        super().add_usage(usage, self._reordered_actions(actions), *args, **kwargs)

    def add_arguments(self, actions):
        super().add_arguments(self._reordered_actions(actions))

    def _fill_text(self, text, width, indent):
        """
        Override to preserve newlines and indentation in help text.
        If the text contains newlines, treat each line as a separate paragraph
        and preserve its formatting rather than rewrapping.
        """
        if '\n' in text:
            # Split by newlines and process each line separately
            lines = text.splitlines()
            result = []
            for line in lines:
                if line.strip() == '':
                    # Preserve empty lines
                    result.append('')
                else:
                    # Indent non-empty lines
                    result.append(indent + line)
            return '\n'.join(result) + '\n'
        return super()._fill_text(text, width, indent)
